import{_ as t}from"./chunks/image12.BRgDBKom.js";import{_ as n,o,c as a,am as i}from"./chunks/framework.CenUaW7a.js";const s="/projects/AiMechaM1/en/advanced-kit/assets/image1.CS6nUu3E.webp",r="/projects/AiMechaM1/en/advanced-kit/assets/image2.CNNNdqMQ.png",l="/projects/AiMechaM1/en/advanced-kit/assets/image3.B573ap8m.png",c="/projects/AiMechaM1/en/advanced-kit/assets/image4.DQzzIv9z.png",d="/projects/AiMechaM1/en/advanced-kit/assets/image5.a-4pUyc3.png",p="/projects/AiMechaM1/en/advanced-kit/assets/image6.MkZf6Em6.png",h="/projects/AiMechaM1/en/advanced-kit/assets/image7.CVKsAJ3B.png",g="/projects/AiMechaM1/en/advanced-kit/assets/image8.abTJu4v4.png",m="/projects/AiMechaM1/en/advanced-kit/assets/image9.D5nlzamu.png",u="/projects/AiMechaM1/en/advanced-kit/assets/image10.CoHZfEuW.png",f="/projects/AiMechaM1/en/advanced-kit/assets/image11.CdZyfx2z.png",M=JSON.parse('{"title":"3.19 Lesson 19: Human Pose Recognition","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3. Course materials/3.19 Lesson 19 Human Pose Recognition.md","filePath":"docs/3. Course materials/3.19 Lesson 19 Human Pose Recognition.md"}'),y={name:"docs/3. Course materials/3.19 Lesson 19 Human Pose Recognition.md"};function b(w,e,v,_,x,k){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="_3-19-lesson-19-human-pose-recognition" tabindex="-1">3.19 Lesson 19: Human Pose Recognition <a class="header-anchor" href="#_3-19-lesson-19-human-pose-recognition" aria-label="Permalink to &quot;3.19 Lesson 19: Human Pose Recognition&quot;">​</a></h1><h2 id="_3-19-1-lesson-introduction" tabindex="-1">3.19.1 Lesson Introduction <a class="header-anchor" href="#_3-19-1-lesson-introduction" aria-label="Permalink to &quot;3.19.1 Lesson Introduction&quot;">​</a></h2><p>Starting with smart security and elderly fall detection scenarios, this lesson introduces a three-tier progressive framework of human body detection, keypoint recognition, and fall detection. Learning how the modular large model recognizes human contours, locates skeletal joints, and evaluates body postures enables the completion of three progressive tasks: triggering the robotic arm to wave hello upon human detection, controlling the car via custom postures, and triggering an audible and visual alarm upon fall detection. Introducing the self-learning mode enables the training of custom posture IDs, illustrating few-shot learning concepts. Combining smart security and elderly care scenarios fosters a technology-for-good mindset, making this an essential lesson toward humanistic reflection.</p><h2 id="_3-19-2-learning-objectives" tabindex="-1">3.19.2 Learning Objectives <a class="header-anchor" href="#_3-19-2-learning-objectives" aria-label="Permalink to &quot;3.19.2 Learning Objectives&quot;">​</a></h2><p><strong>1.</strong> Understand the contour feature recognition principle of human body detection and master the concepts of object bounding boxes and confidence scores. Learn the skeletal joint localization technology of human keypoint detection and understand the composition of the 17-point human skeleton model.</p><p><strong>2.</strong> Switch the K230 module among three operating modes: human detection, human keypoints, and fall detection. Proficiently master core commands, including human presence detection, posture classification judgment, and fall event recognition.</p><p><strong>3.</strong> Establish a three-layer visual cognition framework progressing from &quot;presence detection&quot; to &quot;keypoint localization&quot; and &quot;behavior understanding&quot;. Cultivate operational skills for self-learning training and awareness of parameter tuning.</p><p><strong>4.</strong> Connect human pose recognition technology to real-world application scenarios such as elderly fall monitoring, smart security surveillance, fitness posture correction, and passenger flow analysis, understanding its social value in elderly care, security, fitness, and entertainment.</p><h2 id="_3-19-3-preparation" tabindex="-1">3.19.3 Preparation <a class="header-anchor" href="#_3-19-3-preparation" aria-label="Permalink to &quot;3.19.3 Preparation&quot;">​</a></h2><p><strong>Hardware Preparation</strong>:</p><ul><li><p>AiMecha M1 Mecanum-Wheel Car Advanced Kit</p></li><li><p>Type-C data cable</p></li><li><p>Computer × 1</p></li><li><p>Remote controller</p></li></ul><p><strong>Software Preparation</strong>:</p><ul><li>WonderLab graphical programming software</li></ul><p><strong>Three Functional Tiers of Human Vision</strong>:</p><ul><li><p><strong>Human Detection</strong>: The foundational tier that determines whether a person is present in the frame, counts the number of people, and locates their positions using rectangular bounding boxes.</p></li><li><p><strong>Human Keypoints</strong>: The intermediate tier that locates 17 skeletal keypoints on the human body, including the head, shoulders, elbows, wrists, hips, knees, and ankles, to output skeletal postures.</p></li><li><p><strong>Fall Detection</strong>: The application tier that evaluates temporal changes in keypoints to determine whether a fall event has occurred and outputs an alarm trigger.</p></li></ul><p><strong>Wiring Instructions</strong>:</p><ul><li><p>Connect the K230 screen module to <strong>port A</strong> of the controller.</p></li><li><p>Connect the three bus servos in series to bus port S1 or S2 with IDs 1, 2, and 3.</p></li><li><p>Mount the camera at a recommended height of 1.2 m to 1.5 m with a downward tilt angle of approximately 15° to capture an optimal full-body field of view.</p></li></ul><p><strong>Custom Posture Learning Procedure</strong>:</p><ul><li><p>Select Human Keypoints mode from the K230 module menu.</p></li><li><p>Tap &quot;Learn&quot; to enter the learning state.</p></li><li><p>Strike the target pose, such as standing, sitting, or raising a hand, and hold it steady.</p></li><li><p>Confirm successful learning and assign an ID name to the posture, such as sit, stand, or raise.</p></li><li><p>Call the posture by its assigned ID name in the program for detection.</p></li></ul><p><strong>Fall Detection Principle and Parameters</strong>:</p><ul><li><p>Core judgment feature: The central axis angle of the human body approaches horizontal, whereas normal standing is nearly vertical.</p></li><li><p>Auxiliary feature: The height of the human bounding box drops sharply while its width increases abruptly.</p></li><li><p>Detection delay: Requires confirmation across several consecutive frames to prevent false alarms.</p></li><li><p>Optimal detection distance: Maintain a distance of 2 m to 5 m so that the entire body appears completely within the frame.</p></li></ul><h2 id="_3-19-4-hands-on-project" tabindex="-1">3.19.4 Hands-On Project <a class="header-anchor" href="#_3-19-4-hands-on-project" aria-label="Permalink to &quot;3.19.4 Hands-On Project&quot;">​</a></h2><p><strong>1. Program Logic</strong></p><p>This lesson builds a three-tier progressive human pose perception system. The human detection mode identifies body contours and outputs bounding boxes, driving the robotic arm to lift and lower in a greeting wave whenever a person is detected. The keypoint mode locates 17 skeletal joints and matches them against posture templates, steering the car upon recognizing postures such as sitting or raising a hand. The fall detection mode tracks keypoint sequences over time, triggering a buzzer alarm and flashing red lights if the body axis shifts from vertical to horizontal, accompanied by a sudden drop in body height. All three programs share the unified framework of initialization, data updating, and conditional judgment, demonstrating the cognitive progression of computer vision from presence detection to posture recognition and behavior analysis.</p><img loading="lazy" height="442" width="960" src="'+s+'" class="common_img" style="width:600px;aspect-ratio:960 / 442;"><p>💡<strong>Complete Program Preview:</strong></p><img loading="lazy" height="1128" width="794" src="'+r+'" class="common_img" style="width:460px;aspect-ratio:794 / 1128;"><p><strong>2. Core Commands</strong></p><table tabindex="0"><thead><tr><th style="text-align:center;">Command Category</th><th style="text-align:center;">Core Command</th><th style="text-align:left;">Functional Description</th></tr></thead><tbody><tr><td style="text-align:center;">Human detection</td><td style="text-align:center;"><img loading="lazy" height="68" width="356" src="'+l+'" class="common_img" style="width:200px;aspect-ratio:356 / 68;"></td><td style="text-align:left;">Determines whether a human body is present in the frame and returns a boolean value.</td></tr><tr><td style="text-align:center;">People counting</td><td style="text-align:center;"><img loading="lazy" height="64" width="425" src="'+c+'" class="common_img" style="width:200px;aspect-ratio:425 / 64;"></td><td style="text-align:left;">Counts the number of people detected in the frame, typically used with variables.</td></tr><tr><td style="text-align:center;">Human parameters</td><td style="text-align:center;"><img loading="lazy" height="65" width="602" src="'+d+'" class="common_img" style="width:300px;aspect-ratio:602 / 65;"></td><td style="text-align:left;">Reads the <code>x</code> and <code>y</code> coordinates, width, and height of the centered human bounding box.</td></tr><tr><td style="text-align:center;">Posture recognition</td><td style="text-align:center;"><img loading="lazy" height="66" width="580" src="'+p+'" class="common_img" style="width:300px;aspect-ratio:580 / 66;"></td><td style="text-align:left;">Determines whether a specific self-learned human posture appears in the frame.</td></tr><tr><td style="text-align:center;">Keypoint parameters</td><td style="text-align:center;"><img loading="lazy" height="53" width="695" src="'+h+'" class="common_img" style="width:300px;aspect-ratio:695 / 53;"></td><td style="text-align:left;">Reads detailed data for each skeletal joint, including coordinates and confidence scores.</td></tr><tr><td style="text-align:center;">Fall detection</td><td style="text-align:center;"><img loading="lazy" height="79" width="367" src="'+g+'" class="common_img" style="width:190px;aspect-ratio:367 / 79;"></td><td style="text-align:left;">Determines whether a fall event has occurred to trigger alarm logic.</td></tr></tbody></table><p><strong>3. Complete Program Description</strong></p><p><strong>Task 1: Human Detection Triggering a Robotic Arm Greeting</strong></p><ul><li><p>Initialization settings: At startup, initialize port A, set the running mode to Human Detection, start detection, and reset all three bus servos to position 500 with a running time of 500 ms so the robotic arm returns to its initial neutral posture.</p></li><li><p>Main loop update: Execute <code>Update and save result data</code> as the first step inside the repeat forever loop to synchronize the latest human detection data.</p></li><li><p>Conditional response: If <code>Is person detected?</code> evaluates to true, execute the greeting sequence by setting servo ID 3 to position 500 to raise the robotic arm, waiting 1 s, and setting servo ID 3 to position 300 to lower the robotic arm, creating an &quot;up-and-down waving motion&quot;.</p></li><li><p>Program outcome: Whenever a person enters the camera view, the robotic arm automatically raises to wave hello and remains in the lowered position, waiting for the next detection once the person leaves.</p></li><li><p>Debugging tip: Standing too close to the camera causes the body to exceed the frame boundary and prevents detection, so maintaining a distance of approximately 2 m yields optimal results.</p></li></ul><img loading="lazy" height="674" width="575" src="'+m+'" class="common_img" style="width:460px;aspect-ratio:575 / 674;"><p><strong>Task 2: Custom Posture Controlling Car Steering</strong></p><ul><li><p>Posture learning preparation: Select Human Keypoints mode on the K230 module, learn a custom posture such as a sitting pose, and assign the ID name <code>sit</code> so it can be called using the exact same name in the program.</p></li><li><p>Initialization workflow: At startup, initialize port A, set the running mode to Human Keypoints, and start detection.</p></li><li><p>Main loop structure: After updating the result data inside the repeat forever loop, add a posture judgment branch.</p></li><li><p>Action logic: If the <code>sit</code> posture is detected, command the car to spin left in place at 30% power, wait 2 s, spin right in place at 30% power, wait 4 s, and stop, completing a left turn followed by a return maneuver.</p></li><li><p>Expansion note: Multiple distinct postures can be learned and mapped to different movements, such as standing to move forward, raising a hand to stop, and placing hands on hips to move backward, forming a complete posture control command set.</p></li><li><div class="caution custom-block github-alert"><p class="custom-block-title">CAUTION</p><p></p><p><strong>The posture ID name in the program must match the learned ID name character for character, including case sensitivity. Maintaining a clear and standard posture during learning improves recognition accuracy.</strong></p></div></li></ul><img loading="lazy" height="544" width="470" src="'+u+'" class="common_img" style="width:400px;aspect-ratio:470 / 544;"><p><strong>Task 3: Fall Detection Triggering a Sound and Light Alarm</strong></p><ul><li><p>Mode switching: During initialization, set the running mode to <code>Fall Detection</code>, start detection, and turn off all lights to establish a standby state.</p></li><li><p>Main loop detection: Evaluate the fall detection state after updating the result data inside the <code>repeat forever</code> loop.</p></li><li><p>Alarm response: If <code>Is fall detected?</code> evaluates to true, simultaneously execute three actions: play note D8 for a 1/2 beat in background mode to sound the buzzer alarm, set the onboard RGB LEDs to red, and set all LED beads on the ultrasonic sensor to red for a dual sound-and-light alarm.</p></li><li><p>Continuous alarm: Because the main loop monitors the state continuously, the alarm remains active as long as the fall posture persists and automatically clears once the person stands back up.</p></li><li><p>Simulation test: Slowly crouch down and lean sideways to simulate a fall posture during testing, ensuring the entire body remains inside the frame with a clear change in body axis angle.</p></li></ul><img loading="lazy" height="552" width="462" src="'+f+'" class="common_img" style="width:400px;aspect-ratio:462 / 552;"><p><strong>General Operating Guidelines for Self-Learning Mode</strong></p><ul><li><p>Hold the target posture steady for 2 s to 3 s during learning so the algorithm captures sufficient feature data.</p></li><li><p>Learn the same posture multiple times from slightly different angles to improve recognition robustness.</p></li><li><p>Ensure clear visual differences between different custom postures to prevent confusion between similar poses.</p></li><li><p>Maintain consistent lighting conditions during both learning and usage, as large illumination changes reduce recognition accuracy.</p></li><li><p>Use English letters or numbers when naming learned posture IDs rather than Chinese characters.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The program source files can be downloaded from <a href="https://drive.google.com/drive/folders/1qESIR7n_mxv3oQTrZhNbBTnPKVOk-yT4?usp=sharing" target="_blank" rel="noreferrer">Program Files/Human Pose Recognition</a>.</strong></p></div></li></ul><p><strong>Program Upload</strong>:</p><ul><li><p>Step 1: Power on the mecha controller and insert the Type-C data cable into the data port located above the power switch on the controller.</p></li><li><p>Step 2: Connect the other end of the data cable to a USB port on the computer.</p></li><li><p>Step 3: Click the <strong>Connect device</strong> button at the top of the software interface and select the COM port corresponding to CH340 from the port list.</p></li><li><p>Step 4: Click the upload button in the upper-right corner to download the compiled program to the mecha controller for execution.</p></li></ul><img loading="lazy" height="508" width="960" src="'+t+'" class="common_img" style="width:800px;aspect-ratio:960 / 508;"><h2 id="_3-19-5-expansion-and-advancement" tabindex="-1">3.19.5 Expansion and Advancement <a class="header-anchor" href="#_3-19-5-expansion-and-advancement" aria-label="Permalink to &quot;3.19.5 Expansion and Advancement&quot;">​</a></h2><p><strong>Expansion Project 1: Intelligent People Counting and Passenger Flow Analysis</strong></p><p>Utilize the people counting function to design a passenger flow counter that increments a variable whenever the detected headcount increases, combining entry and exit direction judgments to track foot traffic. Add a time dimension to calculate headcount changes per minute and display crowd density using different RGB LED colors, simulating a commercial shopping mall foot-traffic analysis system and demonstrating the application of computer vision in business intelligence.</p><p><strong>Expansion Project 2: Human Following and Safe Distance Maintenance</strong></p><p>Utilize the human center x-coordinate and bounding box width parameters to implement automatic human following: steer left when the person is on the left side of the frame and steer right when the person is on the right side to keep the target centered. Drive forward when the bounding box width is too small and back up when the width is too large to maintain a safe following distance. Link this with fall detection so the car automatically approaches and sounds an alarm if the person falls, forming a prototype of an intelligent companion robot.</p><h2 id="_3-19-6-q-a" tabindex="-1">3.19.6 Q&amp;A <a class="header-anchor" href="#_3-19-6-q-a" aria-label="Permalink to &quot;3.19.6 Q&amp;A&quot;">​</a></h2><p><strong>Q1: Human detection, human keypoints, and fall detection increase progressively in technical complexity and information depth. How do these three functions build upon one another?</strong></p><p><strong>Answer</strong>: The three functions form a three-tier progression from <strong>simple to complex, from static to dynamic, and from local to holistic</strong>, representing three distinct levels of computer vision in understanding the human body.</p><p><strong>Q2: This lesson uses the self-learning function to let the machine recognize custom-defined postures. What are the similarities and differences between machine self-learning and human learning?</strong></p><p><strong>Answer</strong>: Machine self-learning and human learning <strong>appear similar on the surface but differ fundamentally in essence</strong>, where the core distinction lies in whether learning starts from scratch.</p><h2 id="_3-19-7-technical-support-and-discussion" tabindex="-1">3.19.7 Technical Support and Discussion <a class="header-anchor" href="#_3-19-7-technical-support-and-discussion" aria-label="Permalink to &quot;3.19.7 Technical Support and Discussion&quot;">​</a></h2><p>Join the forum for sharing questions, ideas, or suggestions, and answers will be provided promptly. Click the hyperlink <a href="http://forum.hiwonder.com" target="_blank" rel="noreferrer">Hiwonder Forum</a> or enter the URL in a browser: <a href="http://forum.hiwonder.com" target="_blank" rel="noreferrer">http://forum.hiwonder.com</a></p>',56)])])}const A=n(y,[["render",b]]);export{M as __pageData,A as default};
